function buildMinimalResourcesFaqContent(input: {
  title: string;
  intro: string;
  topics: Array<[string, string, string, string, string]>;
}): ResourcesFaqLocalizedContent {
  const ids = [
    'faq-about',
    'faq-products',
    'faq-operations',
    'faq-quality',
    'faq-warehouse',
    'faq-payment',
    'faq-trade',
  ];

  return {
    title: input.title,
    intro: input.intro,
    footer: 'ANSLIFE | anslife.com | contact@anslife.com | Tel: +84 901 827 555',
    topics: input.topics.map(([nav, title, question, answer, extraQuestion], index) => ({
      id: ids[index],
      nav,
      title,
      items: [
        { question, answer },
        {
          question: extraQuestion,
          answer:
            answer,
        },
      ],
    })),
  };
}

